<?php
declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('users.edit');$id=filter_var(input('id'),FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Not found');}$stmt=db()->prepare('SELECT id,name,email,mobile,is_verified,risk_level FROM users WHERE id=?');$stmt->execute([$id]);$user=$stmt->fetch();if(!$user){http_response_code(404);exit('Not found');}
if(is_post()){verify_csrf();$name=trim((string)input('name'));$email=trim((string)input('email'));$mobile=trim((string)input('mobile'));$verified=input('is_verified')==='1'?1:0;$risk=strtoupper((string)input('risk_level'));if($name===''||strlen($name)>120||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||$mobile===''||strlen($mobile)>30||!in_array($risk,['LOW','MEDIUM','HIGH','CRITICAL'],true))flash('error','Enter valid user details.');else{$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('UPDATE users SET name=?,email=?,mobile=?,is_verified=?,risk_level=?,updated_at=NOW() WHERE id=?')->execute([$name,$email?:null,$mobile,$verified,$risk,$id]);audit_log((int)admin()['id'],'USER_UPDATED','users',(string)$id,$user,['name'=>$name,'email'=>$email,'mobile'=>$mobile,'is_verified'=>$verified,'risk_level'=>$risk]);$pdo->commit();flash('success','User details updated.');redirect('/admin/users/view.php?id='.$id);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof PDOException?'Could not update user. Email or mobile may already exist.':$e->getMessage());}}}
$pageTitle='Edit user #'.$id;require APP_ROOT.'/includes/header.php';?>
<section class="panel"><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Name</label><input name="name" value="<?=e($user['name'])?>" maxlength="120" required></div><div class="field"><label>Email</label><input name="email" type="email" value="<?=e($user['email']??'')?>" maxlength="190"></div><div class="field"><label>Mobile</label><input name="mobile" value="<?=e($user['mobile'])?>" maxlength="30" required></div><div class="field"><label>Verification</label><select name="is_verified"><option value="0" <?=$user['is_verified']?'':'selected'?>>Pending</option><option value="1" <?=$user['is_verified']?'selected':''?>>Verified</option></select></div><div class="field"><label>Risk level</label><select name="risk_level"><?php foreach(['LOW','MEDIUM','HIGH','CRITICAL'] as $r):?><option <?=$r===$user['risk_level']?'selected':''?>><?=$r?></option><?php endforeach?></select></div><div class="field full"><button class="btn">Save user</button> <a class="btn secondary" href="<?=e(app_url('/admin/users/view.php?id='.$id))?>">Cancel</a></div></form></section><?php require APP_ROOT.'/includes/footer.php';
